证据纪律：没有参考素材时，不得虚构论文年份、人物原话、百分比或精确行业数字；数值只能是可复算推导，或在画面中明确标为示意/合成数据。视觉必须真实编码 visualTask 所述关系。
当前 block 角色: visualization。。本 block 教学意图: 滑块调节高度 h，显示最少节点数 N_min(h) 与最大节点数 N_max(h)=2^h-1。
只输出该 block 的 JSON。

{"type": "sim", "engine": "widget", "caption": "拖动滑块改变高度 h，观察最少与最多节点数", "html": "<style>
  .avl-sim { display: flex; flex-direction: column; gap: 1rem; padding: 1rem; }
  .avl-sim .slider-row { display: flex; align-items: center; gap: 1rem; }
  .avl-sim .slider-row label { font-weight: 600; }
  .avl-sim .slider-row input[type=range] { flex: 1; }
  .avl-sim .stats { display: flex; gap: 2rem; justify-content: center; }
  .avl-sim .stat-box { text-align: center; padding: 0.5rem 1rem; border-radius: 8px; background: var(--bg); }
  .avl-sim .stat-box .num { font-size: 1.8rem; font-weight: 700; }
  .avl-sim .stat-box .label { font-size: 0.85rem; color: var(--ink); opacity: 0.7; }
  .avl-sim .stat-box.min { border: 2px solid var(--accent); }
  .avl-sim .stat-box.max { border: 2px solid var(--line); }
  .avl-sim .chart-wrap { position: relative; height: 200px; display: flex; align-items: flex-end; gap: 2rem; justify-content: center; padding: 0 1rem; }
  .avl-sim .bar { width: 60px; border-radius: 6px 6px 0 0; transition: height 0.2s; display: flex; align-items: flex-end; justify-content: center; padding-bottom: 4px; font-weight: 700; color: #fff; font-size: 0.9rem; }
  .avl-sim .bar.min { background: var(--accent); }
  .avl-sim .bar.max { background: var(--line); }
  .avl-sim .bar-label { text-align: center; font-size: 0.8rem; margin-top: 4px; }
</style>
<div class="avl-sim">
  <div class="slider-row">
    <label for="hSlider">高度 h =</label>
    <input type="range" id="hSlider" min="1" max="10" step="1" value="4">
    <span id="hDisplay" style="min-width:2rem;font-weight:700;">4</span>
  </div>
  <div class="stats">
    <div class="stat-box min">
      <div class="num" id="minDisplay">7</div>
      <div class="label">最少节点数 N_min</div>
    </div>
    <div class="stat-box max">
      <div class="num" id="maxDisplay">15</div>
      <div class="label">最大节点数 N_max = 2^h − 1</div>
    </div>
  </div>
  <div class="chart-wrap" id="chartWrap">
    <div style="display:flex;flex-direction:column;align-items:center;">
      <div class="bar min" id="barMin" style="height:70px;">7</div>
      <div class="bar-label">最少</div>
    </div>
    <div style="display:flex;flex-direction:column;align-items:center;">
      <div class="bar max" id="barMax" style="height:150px;">15</div>
      <div class="bar-label">最多</div>
    </div>
  </div>
</div>
<script>
  (function(){
    const slider = document.getElementById('hSlider');
    const hDisp = document.getElementById('hDisplay');
    const minDisp = document.getElementById('minDisplay');
    const maxDisp = document.getElementById('maxDisplay');
    const barMin = document.getElementById('barMin');
    const barMax = document.getElementById('barMax');

    // 预计算 N_min(h) 斐波那契式递推: N_min(1)=1, N_min(2)=2, N_min(h)=N_min(h-1)+N_min(h-2)+1
    const minNodes = [0, 1, 2];
    for(let h=3; h<=10; h++) {
      minNodes[h] = minNodes[h-1] + minNodes[h-2] + 1;
    }

    function update() {
      const h = parseInt(slider.value, 10);
      hDisp.textContent = h;
      const nMin = minNodes[h];
      const nMax = Math.pow(2, h) - 1;
      minDisp.textContent = nMin;
      maxDisp.textContent = nMax;

      // 柱状图高度比例：最大高度 180px，按 nMax 缩放（h=10 时 nMax=1023）
      const maxHeight = 180;
      const scale = maxHeight / 1023;
      const hMin = Math.max(20, nMin * scale);
      const hMax = Math.max(20, nMax * scale);
      barMin.style.height = hMin + 'px';
      barMin.textContent = nMin;
      barMax.style.height = hMax + 'px';
      barMax.textContent = nMax;
    }

    slider.addEventListener('input', update);
    update();
  })();
</script>"}

